const action = $json.body?.action ?? $json.action ?? {};
const data = action.data ?? {};
const card = data.card ?? $json.body?.card ?? $json.card ?? {};
const destinationList = data.listAfter ?? data.list ?? {};
const sourceList = data.listBefore ?? data.previousList ?? data.oldList ?? {};
const targetList = 'Dev To Do';
const previousListName = typeof sourceList.name === 'string' ? sourceList.name : '';
const nextListName = typeof destinationList.name === 'string' ? destinationList.name : '';
const currentListIsTarget = nextListName === targetList || (action.type === 'updateCard' && previousListName === targetList);
const wasCreatedInTarget = action.type === 'createCard' && nextListName === targetList;
const wasMovedToTarget = action.type === 'updateCard' && nextListName === targetList && previousListName !== targetList && previousListName !== '';
const wasUpdatedInTarget = action.type === 'updateCard' && currentListIsTarget;

if (!wasCreatedInTarget && !wasMovedToTarget && !wasUpdatedInTarget) {
  return [];
}

if (!card.id) {
  throw new Error('El evento de Trello no contiene el ID de la card');
}

return [{ json: { cardId: card.id } }];

const card = $json;
let assigneeMap = {};
try {
  assigneeMap = JSON.parse($env.GITHUB_ASSIGNEE_MAP || '{}');
} catch {
  throw new Error('GITHUB_ASSIGNEE_MAP debe ser un JSON valido');
}

const labels = (card.labels ?? []).map((label) => label.name).filter((label) => typeof label === 'string' && label.trim().length > 0);
const assignees = (card.members ?? [])
  .map((member) => member.username)
  .filter((username) => typeof username === 'string' && username.trim().length > 0)
  .map((username) => assigneeMap[username] || username);
const issueMarker = card.id ? `Trello Card ID: ${card.id}` : 'Trello Card ID';
const description = [card.desc ?? '', card.shortUrl ? `Trello: ${card.shortUrl}` : '', issueMarker].filter(Boolean).join('\n\n');

return [{
  json: {
    title: card.name ?? 'Trello card',
    description,
    labels,
    assignees,
    trelloUrl: card.shortUrl ?? '',
    trelloCardId: card.id ?? '',
    issueMarker
  }
}];

const normalized = $('Normalize Trello Card').item.json;
const trelloCardId = normalized.trelloCardId || '';
const searchResult = $json && Array.isArray($json.items) ? $json.items : [];
const matchingIssue = searchResult.find((issue) => {
  if (!issue || !issue.number) return false;
  return true;
});
const payload = {
  title: normalized.title,
  body: normalized.description,
  labels: Array.isArray(normalized.labels) ? normalized.labels : [],
  assignees: Array.isArray(normalized.assignees) ? normalized.assignees : []
};

if (matchingIssue) {
  return [{ json: {
    method: 'PATCH',
    url: `https://api.github.com/repos/${$env.GITHUB_OWNER}/${$env.GITHUB_REPO}/issues/${matchingIssue.number}`,
    body: { title: payload.title, body: payload.body, labels: payload.labels, assignees: payload.assignees },
    number: matchingIssue.number
  }}];
}

return [{ json: {
  method: 'POST',
  url: `https://api.github.com/repos/${$env.GITHUB_OWNER}/${$env.GITHUB_REPO}/issues`,
  body: {
    title: payload.title,
    body: payload.body,
    labels: payload.labels,
    assignees: payload.assignees
  },
  number: null
}}];
